# Evidence ledger for exact input/output files, without editing them.
ledger={}
for name in ['before.jsonl','after.jsonl','openbook.jsonl','resources/train.json','resources/calibration-17b.json','resources/calibration.json']:
 q=runs/name
 ledger[name]={'relative_to_video':'../'+name,'sha256':hashlib.sha256(q.read_bytes()).hexdigest()}
(r/'evidence-lock.json').write_text(json.dumps(ledger,ensure_ascii=False,indent=2)+'\n')
